def populate_shops_and_retire_cards(apps, schema_editor):
    alias = schema_editor.connection.alias
    unlocks = apps.get_model("economy", "LevelUnlock").objects.using(alias)
    offers = apps.get_model("economy", "VirtualOffer").objects.using(alias)
    initial_offers = (
        ("travel-tunic", "Travel tunic", "clothes", 30),
        ("star-hat", "Star hat", "hat", 20),
        ("forest-cape", "Forest cape", "cape", 35),
        ("crystal-staff", "Crystal staff", "staff", 40),
        ("wooden-shield", "Wooden shield", "equipment", 30),
        ("compass-charm", "Compass charm", "accessory", 15),
        ("camp-lantern", "Camp lantern", "decoration", 25),
        ("starlit-theme", "Starlit theme", "theme", 50),
        ("fox-companion", "Fox companion", "pet", 60),
    )
    for code, name, category, cost in initial_offers:
        unlock, _ = unlocks.get_or_create(code=code, defaults={
            "name": name, "kind": "cosmetic", "minimum_level": 1, "earned_by_level": False,
        })
        offers.get_or_create(unlock=unlock, defaults={"category": category, "cost": cost})

    family = apps.get_model("economy", "FamilySettings").objects.using(alias).first()
    try:
        zone = ZoneInfo((family.timezone_name if family else "") or settings.TIME_ZONE)
    except ZoneInfoNotFoundError:
        zone = ZoneInfo(settings.TIME_ZONE)
    day = timezone.localdate(timezone=zone)
    entries = apps.get_model("economy", "LedgerEntry").objects.using(alias)
    children = apps.get_model("economy", "ChildProfile").objects.using(alias)
    tickets = apps.get_model("economy", "LotteryTicket").objects.using(alias).filter(status="open")
    for ticket in tickets.select_related("purchase_ledger_entry").iterator():
        purchase = ticket.purchase_ledger_entry
        valid = (
            purchase and purchase.child_id == ticket.child_id and purchase.kind == "lottery"
            and purchase.source_id == ticket.pk and purchase.delta < 0
            and ticket.result_ledger_entry_id is None
        )
        if not valid:
            ticket.status = "review"
        else:
            reversal = entries.filter(reverses_id=purchase.pk).first()
            if reversal is None:
                child = children.get(pk=ticket.child_id)
                amount = -purchase.delta
                entries.create(
                    child_id=child.pk, delta=amount, balance_before=child.balance,
                    balance_after=child.balance + amount, requested_delta=amount, kind="refund",
                    description="Devolução de cartão surpresa", local_date=day,
                    source_id=ticket.pk, source_type="retired_lottery_ticket",
                    operation_key=f"lottery-retirement:{ticket.pk}", reverses_id=purchase.pk,
                )
                children.filter(pk=child.pk).update(balance=child.balance + amount)
                ticket.status = "refunded"
            elif reversal.child_id == ticket.child_id and reversal.delta == -purchase.delta:
                ticket.status = "refunded"
            else:
                ticket.status = "review"
        ticket.save(update_fields=["status"], using=alias)


